import { Actor } from '../core/entities/Actor';
import { GameWorld } from '../core/GameWorld';
import { findShortestPath } from '../core/Pathfinder';
import { Tile } from '../core/Tile';
import {
  DoorState,
  isAdjacent,
  Point,
  pointsEqual,
  TileType,
  VisibilityState,
} from '../core/types';
import { Camera } from './Camera';
import { SpriteKey, SpriteManager } from './SpriteManager';

export interface HoverTileState {
  readonly position: Point;
  readonly shiftKey: boolean;
}

/**
 * 2D HTML5 Canvas renderer that draws the dungeon map centered on the player:
 * - UNEXPLORED tiles: solid dark void (#07080d)
 * - EXPLORED tiles (Fog of War): 32x32 terrain sprite + dark overlay (hiding items/enemies)
 * - VISIBLE tiles (In Sight): full-brightness 32x32 terrain sprite + visible items & enemies + player at center
 */
export class CanvasRenderer {
  public readonly canvas: HTMLCanvasElement;
  public readonly ctx: CanvasRenderingContext2D;
  public readonly camera: Camera;
  public readonly sprites: SpriteManager;
  private hoverState: HoverTileState | null = null;

  constructor(
    canvas: HTMLCanvasElement,
    camera: Camera = new Camera(canvas.width, canvas.height),
    sprites: SpriteManager = new SpriteManager()
  ) {
    this.canvas = canvas;
    const context = canvas.getContext('2d');
    if (!context) {
      throw new Error('Failed to acquire 2D rendering context from canvas');
    }
    this.ctx = context;
    this.camera = camera;
    this.sprites = sprites;
  }

  public setHoverTile(hover: HoverTileState | null): void {
    this.hoverState = hover;
  }

  public setTileSize(tileSize: number): void {
    this.camera.setTileSize(tileSize);
  }

  public render(world: GameWorld): void {
    const { ctx, camera } = this;
    const width = this.canvas.width;
    const height = this.canvas.height;
    camera.resizeViewport(width, height);

    const tileSize = camera.tileSize;
    const playerPos = world.player.position;

    // Disable smoothing so 32x32 pixel-art sprites scale with crisp edges at any tileSize
    ctx.imageSmoothingEnabled = false;

    // 1. Clear viewport with unexplored dark background
    ctx.fillStyle = '#07080d';
    ctx.fillRect(0, 0, width, height);

    // 2. Render visible & explored map tiles within camera bounds
    const bounds = camera.getVisibleTileBounds(playerPos, world.map.width, world.map.height);

    for (let y = bounds.minY; y <= bounds.maxY; y++) {
      for (let x = bounds.minX; x <= bounds.maxX; x++) {
        const tile = world.map.getTile(x, y);
        if (!tile || tile.visibility === VisibilityState.UNEXPLORED) {
          continue;
        }

        const screenPos = camera.worldToScreen({ x, y }, playerPos);
        const spriteKey = this.getTerrainSpriteKey(tile);
        this.drawSprite(spriteKey, screenPos.x, screenPos.y, tileSize);

        // If tile is in EXPLORED Fog of War, darken it and hide dynamic contents
        if (tile.visibility === VisibilityState.EXPLORED) {
          ctx.fillStyle = 'rgba(5, 8, 18, 0.65)';
          ctx.fillRect(screenPos.x, screenPos.y, tileSize, tileSize);
        }
      }
    }

    // 3. Render items on currently VISIBLE tiles only:
    //    - 1 item stack on tile -> item's own sprite icon
    //    - 2+ item stacks on tile -> dedicated 'item_bag' loot sack icon
    const renderedItemTiles = new Set<string>();
    for (const item of world.getVisibleItems()) {
      const tileKey = `${item.position.x},${item.position.y}`;
      if (renderedItemTiles.has(tileKey)) {
        continue;
      }
      renderedItemTiles.add(tileKey);

      const spriteKey = this.getTileItemSpriteKey(world, item.position);
      if (spriteKey) {
        const screenPos = camera.worldToScreen(item.position, playerPos);
        this.drawSprite(spriteKey, screenPos.x, screenPos.y, tileSize);
      }
    }

    // 4. Render enemies on currently VISIBLE tiles only (plus tiny HP bar overlay if damaged)
    for (const enemy of world.getVisibleEnemies()) {
      const screenPos = camera.worldToScreen(enemy.position, playerPos);
      const validKey: SpriteKey = this.sprites.hasSprite(enemy.spriteKey)
        ? enemy.spriteKey
        : 'enemy_goblin';
      this.drawSprite(validKey, screenPos.x, screenPos.y, tileSize);
      this.drawDamagedActorHpBar(enemy, screenPos, tileSize);
    }

    // 5. Render the player figure at the exact center of the screen (plus tiny HP bar overlay if damaged)
    const playerScreen = camera.worldToScreen(playerPos, playerPos);
    this.drawSprite('player_human', playerScreen.x, playerScreen.y, tileSize);
    this.drawDamagedActorHpBar(world.player, playerScreen, tileSize);

    // 6. Render mouse hover indicator and shortest-path breadcrumb preview
    if (this.hoverState) {
      this.renderHoverHighlight(world, this.hoverState);
    }
  }

  /**
   * Draws a compact 2px-tall health bar across the top of `actor`'s tile whenever `hp < maxHp`.
   * Returns `true` if a bar was drawn, or `false` if the actor is at full HP.
   */
  public drawDamagedActorHpBar(actor: Actor, screenPos: Point, tileSize: number): boolean {
    if (actor.stats.maxHp <= 0 || actor.stats.hp >= actor.stats.maxHp) {
      return false;
    }

    const barWidth = Math.max(8, tileSize - 4);
    const barHeight = Math.max(2, Math.floor(tileSize / 16));
    const ratio = Math.max(0, Math.min(1, actor.stats.hp / actor.stats.maxHp));
    const fillWidth = actor.stats.hp > 0 ? Math.max(1, Math.round(barWidth * ratio)) : 0;

    this.ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
    this.ctx.fillRect(screenPos.x + 2, screenPos.y + 1, barWidth, barHeight);
    if (fillWidth > 0) {
      this.ctx.fillStyle = ratio > 0.4 ? '#22c55e' : '#ef4444';
      this.ctx.fillRect(screenPos.x + 2, screenPos.y + 1, fillWidth, barHeight);
    }
    return true;
  }

  /**
   * Determines which 32x32 sprite key should represent items on a visible tile:
   * - 0 items -> null
   * - 1 item stack -> that item's own spriteKey
   * - 2+ item stacks -> 'item_bag'
   */
  public getTileItemSpriteKey(world: GameWorld, pos: Point): SpriteKey | null {
    if (!world.isTileVisible(pos)) {
      return null;
    }
    const itemsAtTile = world.getItemsAt(pos);
    if (itemsAtTile.length === 0) {
      return null;
    }
    if (itemsAtTile.length >= 2) {
      return 'item_bag';
    }
    const singleKey = itemsAtTile[0].spriteKey;
    return this.sprites.hasSprite(singleKey) ? singleKey : 'item_chest';
  }

  private getTerrainSpriteKey(tile: Tile): SpriteKey {
    if (tile.type === TileType.WALL) {
      return 'tile_wall';
    }
    if (tile.type === TileType.DOOR) {
      const effectiveState =
        tile.visibility === VisibilityState.VISIBLE ? tile.doorState : tile.lastSeenDoorState;
      return effectiveState === DoorState.OPEN ? 'tile_door_open' : 'tile_door_closed';
    }
    return 'tile_floor';
  }

  private drawSprite(key: SpriteKey, screenX: number, screenY: number, size: number): void {
    const spriteCanvas = this.sprites.getSpriteCanvas(key);
    if (spriteCanvas) {
      this.ctx.drawImage(spriteCanvas, screenX, screenY, size, size);
    }
  }

  private renderHoverHighlight(world: GameWorld, hover: HoverTileState): void {
    const tile = world.map.getTile(hover.position.x, hover.position.y);
    if (!tile || tile.visibility === VisibilityState.UNEXPLORED) {
      return;
    }

    const playerPos = world.player.position;
    const size = this.camera.tileSize;

    this.ctx.save();
    this.ctx.lineWidth = 2;

    // 1. Hovering over the player's own tile ('@'): cyan highlight (Pick Up items or Wait 1 turn)
    if (pointsEqual(hover.position, playerPos)) {
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      this.ctx.strokeStyle = 'rgba(56, 189, 248, 0.9)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    // 2. Shift + Hover on an adjacent tile: emerald highlight if Dash-passable, red if blocked
    if (hover.shiftKey && isAdjacent(playerPos, hover.position)) {
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      const canDash =
        tile.isPassable() && world.getBlockingActorAt(hover.position) === null;
      this.ctx.strokeStyle = canDash
        ? 'rgba(16, 185, 129, 0.95)'
        : 'rgba(239, 68, 68, 0.85)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    // 3. Compute shortest path through known tiles
    const path = findShortestPath(world, playerPos, hover.position);
    if (!path || path.length === 0) {
      // Blocked or unreachable tile: red border on hovered tile
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      this.ctx.strokeStyle = 'rgba(239, 68, 68, 0.8)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    const enemyVisible = world.getVisibleEnemies().length > 0;
    const markerSize = Math.max(4, Math.floor(size * 0.22));
    const markerOffset = Math.floor((size - markerSize) / 2);

    if (enemyVisible) {
      // Tactical 1-turn mode: highlight only the 1st step in amber/cyan
      const firstStepScreen = this.camera.worldToScreen(path[0], playerPos);
      this.ctx.fillStyle = 'rgba(245, 158, 11, 0.85)';
      this.ctx.fillRect(
        firstStepScreen.x + markerOffset,
        firstStepScreen.y + markerOffset,
        markerSize,
        markerSize
      );
      this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.95)';
      this.ctx.strokeRect(firstStepScreen.x + 1, firstStepScreen.y + 1, size - 2, size - 2);

      if (path.length > 1) {
        const destScreen = this.camera.worldToScreen(hover.position, playerPos);
        this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.45)';
        this.ctx.strokeRect(destScreen.x + 1, destScreen.y + 1, size - 2, size - 2);
      }
      this.ctx.restore();
      return;
    }

    // Full path preview: draw cyan breadcrumb squares along intermediate path steps
    this.ctx.fillStyle = 'rgba(56, 189, 248, 0.75)';
    for (let i = 0; i < path.length - 1; i++) {
      const stepScreen = this.camera.worldToScreen(path[i], playerPos);
      this.ctx.fillRect(
        stepScreen.x + markerOffset,
        stepScreen.y + markerOffset,
        markerSize,
        markerSize
      );
    }

    // Highlight destination tile (amber for closed door, green for passable floor/open door)
    const destScreen = this.camera.worldToScreen(hover.position, playerPos);
    const effectiveDoorState =
      tile.visibility === VisibilityState.VISIBLE ? tile.doorState : tile.lastSeenDoorState;
    const isDestClosedDoor =
      tile.type === TileType.DOOR && effectiveDoorState === DoorState.CLOSED;

    this.ctx.strokeStyle = isDestClosedDoor
      ? 'rgba(245, 158, 11, 0.95)'
      : 'rgba(74, 222, 128, 0.9)';
    this.ctx.strokeRect(destScreen.x + 1, destScreen.y + 1, size - 2, size - 2);
    this.ctx.restore();
  }
}
