import type { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';

export const DEFAULT_ACTION_TIME_COST = 100;
export const DASH_ACTION_TIME_COST = 50;
export const MELEE_SP_COST = 10;
export const DASH_SP_COST = 10;

export interface ActionResult {
  readonly success: boolean;
  readonly timeCost: number;
  readonly message?: string;
}

/**
 * Command interface for discrete actor actions on the dungeon timeline.
 */
export interface Action {
  readonly type: string;
  readonly isFoodConsumption?: boolean;
  execute(actor: Actor, world: GameWorld): ActionResult;
}

/**
 * Wait/pass turn action that advances the actor's timeline by 1 standard turn
 * silently without emitting a log message, granting 100% SP recovery rate.
 */
export class WaitAction implements Action {
  public readonly type = 'wait';

  public execute(actor: Actor, _world: GameWorld): ActionResult {
    actor.lastActionSpRegenMultiplier = 1;
    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
    };
  }
}
