import { Entity } from '../entities/Entity';
import { Point } from '../types';

export type ItemCategory = 'consumable' | 'weapon' | 'armor' | 'misc';

export interface ItemProps {
  readonly id: string;
  readonly name: string;
  readonly position: Point;
  readonly itemTypeId?: string;
  readonly itemType?: ItemCategory | string;
  readonly spriteKey?: string;
  readonly amount?: number;
  readonly weight?: number;
  readonly stackable?: boolean;
  readonly description?: string;
}

export interface ConcreteItemOptions {
  readonly id?: string;
  readonly position: Point;
  readonly amount?: number;
  readonly weight?: number;
  readonly description?: string;
}

export interface SerializedItem {
  readonly id: string;
  readonly itemTypeId: string;
  readonly itemType: string;
  readonly name: string;
  readonly description: string;
  readonly spriteKey: string;
  readonly position: Point;
  readonly amount: number;
  readonly weight: number;
  readonly stackable: boolean;
  readonly customData?: Record<string, unknown>;
}

/**
 * Base class for all dungeon items that can lie on a floor tile or be held in an Actor's Inventory.
 * Concrete item classes (HealingPotion, IronSword, GoldCoin, etc.) extend this base class.
 */
export class Item extends Entity {
  public readonly itemTypeId: string;
  public readonly itemType: string;
  public readonly description: string;
  public readonly weight: number;
  public readonly stackable: boolean;
  public amount: number;

  constructor(props: ItemProps) {
    super({
      id: props.id,
      name: props.name,
      position: { x: props.position.x, y: props.position.y },
      spriteKey: props.spriteKey ?? 'item_chest',
      blocksMovement: false,
    });
    this.itemTypeId =
      props.itemTypeId ?? props.name.trim().toLowerCase().replace(/\s+/g, '_');
    this.itemType = props.itemType ?? 'misc';
    this.description =
      props.description ?? `A ${props.name.toLowerCase()} found in the dungeon.`;
    this.weight = Math.max(0, props.weight ?? 2);
    this.stackable = props.stackable ?? true;
    this.amount = Math.max(1, Math.floor(props.amount ?? 1));
  }

  public get totalWeight(): number {
    return Number((this.weight * this.amount).toFixed(2));
  }

  public canStackWith(other: Item): boolean {
    return (
      this.stackable &&
      other.stackable &&
      this.itemTypeId === other.itemTypeId &&
      this.name === other.name
    );
  }

  public cloneWithAmount(newAmount: number, newId?: string): Item {
    return new Item({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      name: this.name,
      position: { x: this.position.x, y: this.position.y },
      itemTypeId: this.itemTypeId,
      itemType: this.itemType,
      spriteKey: this.spriteKey,
      amount: newAmount,
      weight: this.weight,
      stackable: this.stackable,
      description: this.description,
    });
  }

  /**
   * Subclasses override this to persist item-specific properties (e.g., healAmount, attackBonus).
   */
  public serializeCustomData(): Record<string, unknown> {
    return {};
  }

  public toSaveData(): SerializedItem {
    const custom = this.serializeCustomData();
    const hasCustom = Object.keys(custom).length > 0;
    return {
      id: this.id,
      itemTypeId: this.itemTypeId,
      itemType: this.itemType,
      name: this.name,
      description: this.description,
      spriteKey: this.spriteKey,
      position: { x: this.position.x, y: this.position.y },
      amount: this.amount,
      weight: this.weight,
      stackable: this.stackable,
      ...(hasCustom ? { customData: custom } : {}),
    };
  }
}
