import { ConcreteItemOptions, Item } from './Item';

export interface TreasureChestOptions extends ConcreteItemOptions {
  readonly isLocked?: boolean;
}

/**
 * Heavy wooden chest reinforced with iron bands.
 */
export class TreasureChest extends Item {
  public readonly isLocked: boolean;

  constructor(options: TreasureChestOptions) {
    super({
      id: options.id ?? `treasure-chest-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Treasure Chest',
      itemTypeId: 'treasure_chest',
      itemType: 'misc',
      position: options.position,
      spriteKey: 'item_chest',
      amount: options.amount ?? 1,
      weight: options.weight ?? 8.0,
      stackable: false,
      description:
        options.description ??
        'A heavy oak chest reinforced with iron bands, holding valuables from the dungeon depths.',
    });
    this.isLocked = options.isLocked ?? false;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): TreasureChest {
    return new TreasureChest({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      isLocked: this.isLocked,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { isLocked: this.isLocked };
  }
}
