import {
  DEFAULT_EAT_MAX_TURNS,
  DEFAULT_EAT_MIN_TURNS,
  FoodItem,
  FoodItemOptions,
} from './FoodItem';
import { Item } from './Item';

/**
 * Freshness thresholds in dungeon timeline ticks (100 ticks = 1 standard turn):
 * - < 100 turns (< 10,000 ticks): 'fresh' (100% satiety, no side effects)
 * - 100..200 turns (10,000..20,000 ticks): 'rotten' (50% satiety, -1 random non-LUK attribute)
 * - > 200 turns (> 20,000 ticks): 'rotted_away' (deleted)
 */
export const MEAT_ROTTEN_THRESHOLD_TICKS = 10_000;
export const MEAT_DECAY_DELETE_THRESHOLD_TICKS = 20_000;

export type MeatFreshness = 'fresh' | 'rotten' | 'rotted_away';

export interface MeatItemOptions extends FoodItemOptions {
  readonly sourceArchetypeId: string;
  readonly sourceEnemyName: string;
  readonly baseSatietyValue: number;
  readonly createdAtTime?: number;
}

/**
 * Perishable meat dropped by defeated animal/beast enemies (`Meat of {enemy_name}`).
 * Uses `stackable: false` internally so each piece tracks its exact `createdAtTime` decay timer,
 * while UI lists visually group matching `(itemTypeId, freshness)` pieces together.
 */
export class MeatItem extends FoodItem {
  public readonly sourceArchetypeId: string;
  public readonly sourceEnemyName: string;
  public readonly createdAtTime: number;

  constructor(options: MeatItemOptions) {
    const createdAtTime = Math.max(0, options.createdAtTime ?? 0);
    const id = options.id ?? `meat-${options.sourceArchetypeId}-${Math.random().toString(36).slice(2, 7)}`;
    super({
      id,
      itemTypeId: `meat_${options.sourceArchetypeId}`,
      itemType: 'consumable',
      name: `Meat of ${options.sourceEnemyName}`,
      description:
        options.description ??
        `Raw meat carved from a defeated ${options.sourceEnemyName}. Best eaten while fresh.`,
      spriteKey: 'item_meat_fresh',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 1.5,
      stackable: false,
      baseSatietyValue: options.baseSatietyValue,
      eatMinTurns: options.eatMinTurns ?? DEFAULT_EAT_MIN_TURNS,
      eatMaxTurns: options.eatMaxTurns ?? DEFAULT_EAT_MAX_TURNS,
    });
    this.sourceArchetypeId = options.sourceArchetypeId;
    this.sourceEnemyName = options.sourceEnemyName;
    this.createdAtTime = createdAtTime;
  }

  public getAgeTicks(currentTimeTicks: number): number {
    return Math.max(0, currentTimeTicks - this.createdAtTime);
  }

  public getFreshness(currentTimeTicks: number): MeatFreshness {
    const age = this.getAgeTicks(currentTimeTicks);
    if (age > MEAT_DECAY_DELETE_THRESHOLD_TICKS) {
      return 'rotted_away';
    }
    if (age >= MEAT_ROTTEN_THRESHOLD_TICKS) {
      return 'rotten';
    }
    return 'fresh';
  }

  public getTurnsUntilNextStage(currentTimeTicks: number): number {
    const age = this.getAgeTicks(currentTimeTicks);
    if (age < MEAT_ROTTEN_THRESHOLD_TICKS) {
      return Math.max(1, Math.ceil((MEAT_ROTTEN_THRESHOLD_TICKS - age) / 100));
    }
    if (age <= MEAT_DECAY_DELETE_THRESHOLD_TICKS) {
      return Math.max(0, Math.ceil((MEAT_DECAY_DELETE_THRESHOLD_TICKS - age) / 100));
    }
    return 0;
  }

  public override getEffectiveSatietyValue(currentTimeTicks: number): number {
    const freshness = this.getFreshness(currentTimeTicks);
    if (freshness === 'rotten') {
      return Math.max(1, Math.floor(this.baseSatietyValue * 0.5));
    }
    return this.baseSatietyValue;
  }

  public override getEffectiveSpriteKey(currentTimeTicks: number): string {
    return this.getFreshness(currentTimeTicks) === 'rotten'
      ? 'item_meat_rotten'
      : 'item_meat_fresh';
  }

  public syncSprite(currentTimeTicks: number): void {
    this.spriteKey = this.getEffectiveSpriteKey(currentTimeTicks);
  }

  public override cloneWithAmount(newAmount: number, newId?: string): MeatItem {
    const cloned = new MeatItem({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { ...this.position },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      sourceArchetypeId: this.sourceArchetypeId,
      sourceEnemyName: this.sourceEnemyName,
      baseSatietyValue: this.baseSatietyValue,
      createdAtTime: this.createdAtTime,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      isMeatItem: true,
      sourceArchetypeId: this.sourceArchetypeId,
      sourceEnemyName: this.sourceEnemyName,
      baseSatietyValue: this.baseSatietyValue,
      createdAtTime: this.createdAtTime,
      eatMinTurns: this.eatMinTurns,
      eatMaxTurns: this.eatMaxTurns,
    };
  }
}

export function isMeatItem(item: Item): item is MeatItem {
  return item instanceof MeatItem;
}
