export type ActiveModalType =
  | 'none'
  | 'title'
  | 'savelist'
  | 'save_confirm'
  | 'log'
  | 'help'
  | 'inventory'
  | 'pickup'
  | 'drop'
  | 'eat'
  | 'config'
  | 'actions'
  | 'gameover';

export type ActionMenuOptionId =
  | 'pickup'
  | 'inventory'
  | 'drop'
  | 'attack'
  | 'dash'
  | 'close_door'
  | 'wait'
  | 'log'
  | 'help'
  | 'config'
  | 'eat'
  | 'save';

export type TitleMenuOptionId = 'new_game' | 'load_game' | 'config';

/**
 * Converts internal timeline ticks into the displayed turn/time counter: Math.floor(ticks / 100).
 */
export function formatDisplayTime(ticks: number): number {
  return Math.floor(ticks / 100);
}

