import { ConcreteItemOptions, Item } from './Item';

export interface HealingPotionOptions extends ConcreteItemOptions {
  readonly healAmount?: number;
}

/**
 * Consumable potion that restores HP when consumed.
 */
export class HealingPotion extends Item {
  public readonly healAmount: number;

  constructor(options: HealingPotionOptions) {
    super({
      id: options.id ?? `healing-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Healing Potion',
      itemTypeId: 'healing_potion',
      itemType: 'consumable',
      position: options.position,
      spriteKey: 'item_potion',
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      description:
        options.description ??
        'A crimson herbal draught that restores 25 HP when consumed.',
    });
    this.healAmount = options.healAmount ?? 25;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): HealingPotion {
    return new HealingPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      healAmount: this.healAmount,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return { healAmount: this.healAmount };
  }
}
