export type ItemDeserializer = (data: SerializedItem) => Item;

const itemDeserializerRegistry = new Map<string, ItemDeserializer>();

/**
 * Registers a concrete Item subclass deserializer under its `itemTypeId`.
 * Future item classes only need to register here to gain full Save/Load support.
 */
export function registerItemDeserializer(
  itemTypeId: string,
  deserializer: ItemDeserializer
): void {
  itemDeserializerRegistry.set(itemTypeId, deserializer);
}

/**
 * Reconstructs a concrete `Item` subclass instance from `SerializedItem` data,
 * falling back to the base `Item` class if an unknown or ad-hoc `itemTypeId` is encountered.
 */
export function deserializeItem(data: SerializedItem): Item {
  const factory = itemDeserializerRegistry.get(data.itemTypeId);
  if (factory) {
    return factory(data);
  }
  if (data.customData?.isMeatItem === true || data.itemTypeId.startsWith('meat_')) {
    const sourceArchetypeId =
      typeof data.customData?.sourceArchetypeId === 'string'
        ? data.customData.sourceArchetypeId
        : data.itemTypeId.replace(/^meat_/, '');
    const sourceEnemyName =
      typeof data.customData?.sourceEnemyName === 'string'
        ? data.customData.sourceEnemyName
        : data.name.replace(/^Meat of\s+/i, '');
    const baseSatietyValue =
      typeof data.customData?.baseSatietyValue === 'number'
        ? data.customData.baseSatietyValue
        : 100;
    const createdAtTime =
      typeof data.customData?.createdAtTime === 'number' ? data.customData.createdAtTime : 0;
    const eatMinTurns =
      typeof data.customData?.eatMinTurns === 'number' ? data.customData.eatMinTurns : undefined;
    const eatMaxTurns =
      typeof data.customData?.eatMaxTurns === 'number' ? data.customData.eatMaxTurns : undefined;
    const meat = new MeatItem({
      id: data.id,
      position: { x: data.position.x, y: data.position.y },
      amount: data.amount,
      weight: data.weight,
      description: data.description,
      sourceArchetypeId,
      sourceEnemyName,
      baseSatietyValue,
      createdAtTime,
      eatMinTurns,
      eatMaxTurns,
    });
    meat.spriteKey = data.spriteKey;
    return meat;
  }
  if (data.customData?.isFoodItem === true) {
    const baseSatietyValue =
      typeof data.customData?.baseSatietyValue === 'number'
        ? data.customData.baseSatietyValue
        : 100;
    return new FoodItem({
      id: data.id,
      name: data.name,
      position: { x: data.position.x, y: data.position.y },
      itemTypeId: data.itemTypeId,
      itemType: data.itemType,
      spriteKey: data.spriteKey,
      amount: data.amount,
      weight: data.weight,
      stackable: data.stackable,
      description: data.description,
      baseSatietyValue,
      eatMinTurns:
        typeof data.customData?.eatMinTurns === 'number' ? data.customData.eatMinTurns : undefined,
      eatMaxTurns:
        typeof data.customData?.eatMaxTurns === 'number' ? data.customData.eatMaxTurns : undefined,
    });
  }
  return new Item({
    id: data.id,
    name: data.name,
    position: { x: data.position.x, y: data.position.y },
    itemTypeId: data.itemTypeId,
    itemType: data.itemType,
    spriteKey: data.spriteKey,
    amount: data.amount,
    weight: data.weight,
    stackable: data.stackable,
    description: data.description,
  });
}

